package com.niyava.ecom.productservice.repository;import com.niyava.ecom.productservice.entity.category.Category;import org.springframework.data.mongodb.repository.MongoRepository;import org.springframework.data.mongodb.repository.Query;import java.util.List;public interface CategoryRepository extends MongoRepository<Category, String> {    Category findByName(String name);    @Query("{ 'name':{$regex:?0, $options:'i'} }")    List<Category> findCategoriesByNameRegex(String searchString);}